"""Generate SYNTHETIC RLTech AC 8080 page fixtures.

These fixtures are NOT captured from a device. They are built from SDK source
so parser tests can run before real (sanitized) captures from stage 0 exist.
Replace or extend them with real samples once the AC is reachable.

Sources used (git_FTTR SDK):
- apps/private/webPage/Router/e8c_ml_new_utf8/boaroot/cgi-bin/ap_online_list.asp:22
  ``var AP_manage = '<% tcWebApi_JsonHook("XQuery_AP_List", ...) %>';``
- apps/private/webPage/Router/e8c_ml_new_utf8/boaroot/cgi-bin/ap_online_detail.asp:19-33
  ``var lan_pon_num``, ``var list_ap ='<% ...XQuery_AP_Info... %>'`` and
  ``let list_pon = '<% ...registerinfo... %>';``
- apps/public/boa-asp/src/asp/asp_handler.c:3188-3270 (XQuery_AP_List) and
  :3274-3330 (XQuery_AP_Info): ubus output is read into a 1024-byte buffer
  (AP info only), every space/tab is removed and newlines become one space.
- apps/public/boa-asp/src/asp/asp_handler.c:4686-4770 (registerinfo): same
  1024-byte buffer, tabs removed but spaces kept.
- apps/private/acap_db/acap_db_ap_list.c:7-12, :85-92 column order; and
  acap_db_common.c list_callback/single_info_callback: every column is emitted
  as a JSON string, SQL NULL becomes the literal string "NULL".
- source/lan_mgr/slaveMgr_v2/server/ubus/object/obj_slavemgr_ap.c:204-270:
  ``respCode`` is a u32 added before the DB JSON.
- apps/private/ap_server/ap_support.c:559-568: registerinfo ``data`` is a JSON
  *string* containing an escaped object; "1970-01-01 08:00:00" is the
  "never" sentinel for last_down_time/last_dying_gasptime.

Identities (MAC/SN/IP) are fake: locally administered MACs 02:00:5E:10:00:0x,
SN RLGM5E10000x and TEST-NET-1 addresses 192.0.2.x.

Run: python3 tests/fixtures/generate_synthetic.py
"""

from __future__ import annotations

import json
from pathlib import Path

HERE = Path(__file__).parent
BOA_AP_INFO_BUFFER = 1024

HEADER = (
    "<!-- SYNTHETIC fixture generated by tests/fixtures/generate_synthetic.py;"
    " NOT a device capture. Based on git_FTTR {source}. -->\n"
)


def ubus_pretty(value: object, indent: int = 0) -> str:
    """Approximate libubox blobmsg_format_json_indent output (tab indented)."""
    pad = "\t" * indent
    inner = "\t" * (indent + 1)
    if isinstance(value, dict):
        if not value:
            return "{ }"
        items = [
            f'{inner}{json.dumps(key)}: {ubus_pretty(item, indent + 1)}'
            for key, item in value.items()
        ]
        return "{\n" + ",\n".join(items) + "\n" + pad + "}"
    if isinstance(value, list):
        items = [f"{inner}{ubus_pretty(item, indent + 1)}" for item in value]
        return "[\n" + ",\n".join(items) + "\n" + pad + "]"
    return json.dumps(value)


def boa_strip_all_whitespace(text: str, *, limit: int | None = None) -> str:
    """Mimic XQuery_AP_List/XQuery_AP_Info post-processing."""
    if limit is not None:
        # fgets+snprintf into char[limit] keeps at most limit-1 bytes.
        text = text.encode("utf-8")[: limit - 1].decode("utf-8", "ignore")
    out = []
    for char in text:
        if char == "\n":
            out.append(" ")
        elif char in " \t\b":
            continue
        else:
            out.append(char)
    return "".join(out)


def boa_strip_tabs(text: str, *, limit: int | None = None) -> str:
    """Mimic registerinfo post-processing (spaces are kept)."""
    if limit is not None:
        text = text.encode("utf-8")[: limit - 1].decode("utf-8", "ignore")
    return "".join(
        " " if char == "\n" else "" if char in "\t\b" else char for char in text
    )


