def ap_info_row(list_row: dict[str, str], **overrides: str) -> dict[str, str]:
    """Build an XQuery_AP_Info data object in acap_db_ap_list.c:85-92 order."""
    row = {
        "Model": list_row["Model"],
        "IP": list_row["IP"],
        "Version": list_row["Version"],
        "Mac": list_row["Mac"],
        "Status": list_row["Status"],
        "Profile": list_row["Profile"],
        "ChannelG24": list_row["ChannelG24"],
        "ChannelG5": list_row["ChannelG5"],
        "Assoc": list_row["Assoc"],
        "Alias": list_row["Alias"],
        "SN": list_row["SN"],
        "Uplink": list_row["Uplink"],
        "UplinkPort": list_row["UplinkPort"],
        "Fingerprint": "5A0C1B2E-3F40-4D51-8E62-7F8091A2B3C4",
        "LastOfflineReason": "",
        "BssidG24": list_row["BssidG24"],
        "BssidG5": list_row["BssidG5"],
        "SysDuration": "86461",
        "RamSize": "536870912",
        "FlashSize": "268435456",
        "DevName": "FTTRSub_100001",
        "CPUUsage": "7",
        "CPUTemp": "63",
        "MEMUsage": "41",
        "FlashUsage": "86",
        "DevSN": list_row["DevSN"],
        "UpgradeFlag": list_row["UpgradeFlag"],
        "ProfileIdx": list_row["ProfileIdx"],
        "OptTxPower": list_row["OptTxPower"],
        "OptRxPower": list_row["OptRxPower"],
    }
    row.update(overrides)
    return row


