def list_page(rows: list[dict[str, str]]) -> str:
    reply = {
        "respCode": 0,
        "total": len(rows),
        "count": len(rows),
        "data": {"list": rows},
    }
    body = boa_strip_all_whitespace(ubus_pretty(reply) + "\n")
    return (
        HEADER.format(source="ap_online_list.asp:22 + asp_handler.c:3188")
        + "<HTML><BODY>\n<script language=\"JavaScript\" type=\"text/javascript\">\n"
        + f"        var AP_manage = '{body}';\n"
        + "        var ret = JSON.parse(AP_manage);\n"
        + "</script></BODY></HTML>\n"
    )


def detail_page(
    info: dict[str, str] | None,
    pon_reply: dict[str, object] | None,
    *,
    lan_pon_num: str = "2",
    source: str,
) -> str:
    if info is None:
        list_ap = ""
    else:
        list_ap = boa_strip_all_whitespace(
            ubus_pretty({"respCode": 0, "data": info}) + "\n",
            limit=BOA_AP_INFO_BUFFER,
        )
    if pon_reply is None:
        list_pon = ""
    else:
        list_pon = boa_strip_tabs(
            ubus_pretty(pon_reply) + "\n", limit=BOA_AP_INFO_BUFFER
        )
    return (
        HEADER.format(source=source)
        + "<HTML><HEAD>\n<SCRIPT>\n"
        + f"var lan_pon_num = '{lan_pon_num}';\n"
        + f"var list_ap ='{list_ap}'\n"
        + "var ap_list_info = JSON.parse(list_ap)\n"
        + f"let list_pon = '{list_pon}';\n"
        + "let modifiedStr = list_pon.replace(/\"({[^{}]+})\"/g, '$1');\n"
        + "</SCRIPT></HEAD><BODY></BODY></HTML>\n"
    )


def pon_string_reply(data: dict[str, object]) -> dict[str, object]:
    # registerinfo "data" is a JSON string holding a serialized object. The
    # inner object comes from json-c, which escapes "/" as "\\/" (see the
    # "N\\\\\\/A" test vector in ap_support.c:566); libubox does not.
    inner = json.dumps(data, separators=(", ", ": ")).replace("/", "\\/")
    return {"result": 0, "data": inner}


def main() -> None:
    detail_src = "ap_online_detail.asp:19-33 + asp_handler.c:3274,4686"
    files = {
        "synthetic_ap_online_list.html": list_page([AP1, AP2]),
        # Full detail: list_ap + list_pon with data as an escaped JSON string.
        "synthetic_ap_online_detail_full.html": detail_page(
            ap_info_row(AP1, LastOfflineReason="Reboot"),
            pon_string_reply(PON_AP1),
            source=detail_src,
        ),
        # PON lookup failed (result 9 per ap_online_detail.asp:288,339) so the
        # page falls back to list_ap OptTx/RxPower; last_down_time is absent.
        "synthetic_ap_online_detail_no_pon.html": detail_page(
            ap_info_row(
                AP2,
                DevName="FTTRSub_100002",
                SysDuration="3605",
                OptTxPower="1.98",
                OptRxPower="-20.05",
                LastOfflineReason="Offline",
            ),
            {"result": 9},
            source=detail_src,
        ),
        # registerinfo produced no output (ubus object missing): empty string.
        "synthetic_ap_online_detail_empty_pon.html": detail_page(
            ap_info_row(AP1),
            None,
            source=detail_src,
        ),
        # Long field values push XQuery_AP_Info past the 1024-byte boa buffer
        # (asp_handler.c:3276), so list_ap JSON is cut mid-object.
        "synthetic_ap_online_detail_truncated.html": detail_page(
            ap_info_row(
                AP1,
                Alias="Living_Room_Upstairs_Corridor_Ceiling_AP_Primary_Unit_01"
                "_Second_Floor_East_Wing",
                DevName="FTTRSub_100001_with_a_really_long_hostname_value_x"
                "_that_keeps_going_for_padding_purposes_only",
                LastOfflineReason="LinkDown_OpticalSignalLost_Timeout_Retry"
                "_After_Watchdog_Expired_On_Uplink_Port_Six_Of_Controller",
                Profile="Enterprise_Deployment_Profile_Group_A_Default",
            ),
            pon_string_reply(PON_AP1),
            source=detail_src,
        ),
    }
    for name, text in files.items():
        (HERE / name).write_text(text, encoding="utf-8")
        print(f"wrote {name} ({len(text)} bytes)")


if __name__ == "__main__":
    main()
